CREATE TABLE public.salt_empresa(empresa_id uuid PRIMARY KEY REFERENCES public.empresas(id), salt text NOT NULL DEFAULT encode(extensions.gen_random_bytes(32),'hex'), criado_em timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.salt_empresa TO service_role;
ALTER TABLE public.salt_empresa ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.indice_titulares(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), empresa_id uuid NOT NULL REFERENCES public.empresas(id), produto_id uuid NOT NULL REFERENCES public.registro_operacoes(id), produto_indice integer NOT NULL DEFAULT 0 CHECK(produto_indice>=0), identificador_hash text NOT NULL CHECK(identificador_hash ~ '^[a-f0-9]{64}$'), tipo_identificador text NOT NULL CHECK(tipo_identificador IN ('CPF','CNPJ','EMAIL','MATRICULA','OUTRO')), localizacao_tecnica text NOT NULL CHECK(length(btrim(localizacao_tecnica))>0), criado_em timestamptz NOT NULL DEFAULT now(), criado_por uuid NOT NULL REFERENCES public.profiles(id), UNIQUE(empresa_id,produto_id,produto_indice,identificador_hash,tipo_identificador));
GRANT SELECT ON public.indice_titulares TO authenticated;
GRANT ALL ON public.indice_titulares TO service_role;
ALTER TABLE public.indice_titulares ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.solicitacoes_titular(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),empresa_id uuid NOT NULL REFERENCES public.empresas(id),protocolo text NOT NULL UNIQUE DEFAULT ('TIT-'||to_char(now(),'YYYYMMDD')||'-'||substr(gen_random_uuid()::text,1,8)),canal text NOT NULL,identificador_hash text NOT NULL CHECK(identificador_hash ~ '^[a-f0-9]{64}$'),direito_solicitado text NOT NULL CHECK(direito_solicitado IN ('I','II','III','IV','V','VI','VII','VIII','IX')),descricao text NOT NULL DEFAULT '',data_recebimento date NOT NULL,prazo_resposta date NOT NULL,status text NOT NULL CHECK(status IN ('ABERTA','EM_ANALISE','ENCAMINHADA_CONTROLADOR','RESPONDIDA','NEGADA')),fundamento_negativa text, fundamento_normativo_id uuid REFERENCES public.biblioteca_normativa(id),respondido_em timestamptz,responsavel_id uuid NOT NULL REFERENCES public.profiles(id),criado_em timestamptz NOT NULL DEFAULT now(),tipo_prazo text NOT NULL CHECK(tipo_prazo IN ('LEGAL','METODO')),produto_id uuid REFERENCES public.registro_operacoes(id),CHECK(status<>'NEGADA' OR (length(btrim(fundamento_negativa))>0 AND fundamento_normativo_id IS NOT NULL)),CHECK(prazo_resposta=data_recebimento+15));
GRANT SELECT ON public.solicitacoes_titular TO authenticated;
GRANT ALL ON public.solicitacoes_titular TO service_role;
ALTER TABLE public.solicitacoes_titular ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.autorizar_titulares(_empresa uuid) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c text; BEGIN
IF auth.uid() IS NULL OR NOT (public.has_role(auth.uid(),'ADMIN_SISTEMA') OR public.has_role(auth.uid(),'DPO_OPERACIONAL')) THEN RAISE EXCEPTION 'Acesso restrito ao DPO ou administrador'; END IF;
SELECT cnpj INTO c FROM public.empresas WHERE id=_empresa;
IF c IS NULL OR NOT public.cnpj_liberado(c) OR (NOT public.has_role(auth.uid(),'ADMIN_SISTEMA') AND _empresa IS DISTINCT FROM public.minha_empresa_id()) THEN RAISE EXCEPTION 'Empresa não autorizada'; END IF; RETURN c; END $$;
REVOKE ALL ON FUNCTION public.autorizar_titulares(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.autorizar_titulares(uuid) TO authenticated;
CREATE POLICY indice_leitura ON public.indice_titulares FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'ADMIN_SISTEMA') OR (empresa_id=public.minha_empresa_id() AND public.has_role(auth.uid(),'DPO_OPERACIONAL')));
CREATE POLICY indice_empresa_ativa ON public.indice_titulares AS RESTRICTIVE FOR ALL TO authenticated USING(public.cnpj_liberado((SELECT cnpj FROM public.empresas WHERE id=empresa_id)));
CREATE POLICY solicitacoes_leitura ON public.solicitacoes_titular FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'ADMIN_SISTEMA') OR (empresa_id=public.minha_empresa_id() AND public.has_role(auth.uid(),'DPO_OPERACIONAL')));
CREATE POLICY solicitacoes_empresa_ativa ON public.solicitacoes_titular AS RESTRICTIVE FOR ALL TO authenticated USING(public.cnpj_liberado((SELECT cnpj FROM public.empresas WHERE id=empresa_id)));
CREATE OR REPLACE FUNCTION public.hash_titular_interno(_empresa uuid,_identificador text,_tipo text) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,extensions AS $$ DECLARE s text; v text; BEGIN
IF length(btrim(coalesce(_identificador,'')))=0 OR length(_identificador)>320 OR _tipo NOT IN ('CPF','CNPJ','EMAIL','MATRICULA','OUTRO') THEN RAISE EXCEPTION 'Identificador inválido'; END IF;
INSERT INTO public.salt_empresa(empresa_id) VALUES(_empresa) ON CONFLICT DO NOTHING;
SELECT salt INTO s FROM public.salt_empresa WHERE empresa_id=_empresa;
v:=CASE WHEN _tipo IN ('CPF','CNPJ') THEN regexp_replace(_identificador,'[^0-9]','','g') WHEN _tipo='EMAIL' THEN lower(btrim(_identificador)) ELSE btrim(_identificador) END;
IF v='' THEN RAISE EXCEPTION 'Identificador inválido'; END IF;
RETURN encode(digest(s||'|'||_tipo||'|'||v,'sha256'),'hex'); END $$;
REVOKE ALL ON FUNCTION public.hash_titular_interno(uuid,text,text) FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.indexar_titular(_empresa_id uuid,_produto_id uuid,_produto_indice integer,_identificador text,_tipo text,_localizacao text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c text; h text; i uuid; BEGIN
c:=public.autorizar_titulares(_empresa_id);
IF NOT EXISTS(SELECT 1 FROM public.registro_operacoes WHERE id=_produto_id AND empresa_cnpj=c AND excluido_em IS NULL AND NOT removida_do_dossie AND jsonb_array_length(produtos_tratamento)>_produto_indice) THEN RAISE EXCEPTION 'PRT não pertence à empresa ou não está ativo'; END IF;
IF length(btrim(coalesce(_localizacao,'')))=0 OR length(_localizacao)>2000 OR position(lower(btrim(_identificador)) in lower(_localizacao))>0 THEN RAISE EXCEPTION 'Localização técnica inválida: não inclua identificador'; END IF;
h:=public.hash_titular_interno(_empresa_id,_identificador,_tipo);
INSERT INTO public.indice_titulares(empresa_id,produto_id,produto_indice,identificador_hash,tipo_identificador,localizacao_tecnica,criado_por) VALUES(_empresa_id,_produto_id,_produto_indice,h,_tipo,btrim(_localizacao),auth.uid()) ON CONFLICT(empresa_id,produto_id,produto_indice,identificador_hash,tipo_identificador) DO UPDATE SET localizacao_tecnica=excluded.localizacao_tecnica RETURNING id INTO i;
PERFORM public.registrar_acesso(CASE WHEN public.has_role(auth.uid(),'ADMIN_SISTEMA') THEN 'ADMIN_SISTEMA'::public.app_role ELSE 'DPO_OPERACIONAL'::public.app_role END,'INSERT','indice_titulares','Vínculo técnico registrado: '||i,c,NULL); RETURN i; END $$;
CREATE OR REPLACE FUNCTION public.localizar_titular(_empresa_id uuid,_identificador text,_tipo text DEFAULT 'CPF') RETURNS TABLE(indice_id uuid,produto_id uuid,codigo text,prt text,localizacao_tecnica text,papel_agente text) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c text; h text; BEGIN
c:=public.autorizar_titulares(_empresa_id);h:=public.hash_titular_interno(_empresa_id,_identificador,_tipo);
PERFORM public.registrar_acesso(CASE WHEN public.has_role(auth.uid(),'ADMIN_SISTEMA') THEN 'ADMIN_SISTEMA'::public.app_role ELSE 'DPO_OPERACIONAL'::public.app_role END,'SELECT','indice_titulares','Consulta de localização de titular',c,NULL);
RETURN QUERY SELECT i.id,r.id,r.codigo,('PRT-'||(i.produto_indice+1)::text||' · '||(r.produtos_tratamento->i.produto_indice->>'nome')),i.localizacao_tecnica,r.papel_agente::text FROM public.indice_titulares i JOIN public.registro_operacoes r ON r.id=i.produto_id WHERE i.empresa_id=_empresa_id AND i.identificador_hash=h AND i.tipo_identificador=_tipo AND r.empresa_cnpj=c AND r.excluido_em IS NULL AND NOT r.removida_do_dossie; END $$;
CREATE OR REPLACE FUNCTION public.criar_solicitacao_titular(_empresa_id uuid,_identificador text,_tipo text,_direito text,_canal text,_descricao text,_recebimento date,_produto_id uuid DEFAULT NULL) RETURNS public.solicitacoes_titular LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c text; h text; r public.solicitacoes_titular; p text; BEGIN
c:=public.autorizar_titulares(_empresa_id); h:=public.hash_titular_interno(_empresa_id,_identificador,_tipo);
IF _direito NOT IN ('I','II','III','IV','V','VI','VII','VIII','IX') OR _recebimento IS NULL OR _recebimento>current_date OR length(btrim(coalesce(_canal,'')))=0 THEN RAISE EXCEPTION 'Direito, canal ou recebimento inválido'; END IF;
IF length(coalesce(_descricao,''))>4000 OR position(lower(btrim(_identificador)) in lower(coalesce(_descricao,'')))>0 THEN RAISE EXCEPTION 'Descrição inválida: não inclua identificador'; END IF;
IF _produto_id IS NOT NULL THEN SELECT papel_agente INTO p FROM public.registro_operacoes WHERE id=_produto_id AND empresa_cnpj=c AND excluido_em IS NULL AND NOT removida_do_dossie; IF NOT FOUND THEN RAISE EXCEPTION 'Processo de outra empresa ou inativo'; END IF; END IF;
INSERT INTO public.solicitacoes_titular(empresa_id,canal,identificador_hash,direito_solicitado,descricao,data_recebimento,prazo_resposta,status,responsavel_id,tipo_prazo,produto_id) VALUES(_empresa_id,btrim(_canal),h,_direito,coalesce(_descricao,''),_recebimento,_recebimento+15,CASE WHEN p='OPERADOR' THEN 'ENCAMINHADA_CONTROLADOR' ELSE 'ABERTA' END,auth.uid(),CASE WHEN _direito IN ('I','II') THEN 'LEGAL' ELSE 'METODO' END,_produto_id) RETURNING * INTO r;
PERFORM public.registrar_acesso(CASE WHEN public.has_role(auth.uid(),'ADMIN_SISTEMA') THEN 'ADMIN_SISTEMA'::public.app_role ELSE 'DPO_OPERACIONAL'::public.app_role END,'INSERT','solicitacoes_titular','Solicitação '||r.protocolo||' registrada: '||r.status,c,NULL); RETURN r; END $$;
CREATE OR REPLACE FUNCTION public.atualizar_solicitacao_titular(_id uuid,_status text,_fundamento_id uuid DEFAULT NULL,_fundamento text DEFAULT '') RETURNS public.solicitacoes_titular LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.solicitacoes_titular; c text; BEGIN
SELECT * INTO r FROM public.solicitacoes_titular WHERE id=_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Solicitação inexistente'; END IF;c:=public.autorizar_titulares(r.empresa_id);
IF r.status IN ('NEGADA','RESPONDIDA') THEN RAISE EXCEPTION 'Atendimento finalizado'; END IF;
IF _status NOT IN ('EM_ANALISE','ENCAMINHADA_CONTROLADOR','RESPONDIDA','NEGADA') THEN RAISE EXCEPTION 'Status inválido'; END IF;
IF _status='NEGADA' AND (length(btrim(coalesce(_fundamento,'')))=0 OR NOT EXISTS(SELECT 1 FROM public.biblioteca_normativa WHERE id=_fundamento_id AND status='VERIFICADA' AND categoria IN ('REGIME_GERAL','LEI_ESPECIAL_SETORIAL'))) THEN RAISE EXCEPTION 'Negativa exige fundamento com dispositivo legal verificado'; END IF;
UPDATE public.solicitacoes_titular SET status=_status,fundamento_negativa=CASE WHEN _status='NEGADA' THEN btrim(_fundamento) END,fundamento_normativo_id=CASE WHEN _status='NEGADA' THEN _fundamento_id END,respondido_em=CASE WHEN _status IN ('RESPONDIDA','NEGADA') THEN now() END WHERE id=_id RETURNING * INTO r;
PERFORM public.registrar_acesso(CASE WHEN public.has_role(auth.uid(),'ADMIN_SISTEMA') THEN 'ADMIN_SISTEMA'::public.app_role ELSE 'DPO_OPERACIONAL'::public.app_role END,'UPDATE','solicitacoes_titular','Solicitação '||r.protocolo||': '||r.status,c,NULL); RETURN r; END $$;
REVOKE ALL ON FUNCTION public.indexar_titular(uuid,uuid,integer,text,text,text),public.localizar_titular(uuid,text,text),public.criar_solicitacao_titular(uuid,text,text,text,text,text,date,uuid),public.atualizar_solicitacao_titular(uuid,text,uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.indexar_titular(uuid,uuid,integer,text,text,text),public.localizar_titular(uuid,text,text),public.criar_solicitacao_titular(uuid,text,text,text,text,text,date,uuid),public.atualizar_solicitacao_titular(uuid,text,uuid,text) TO authenticated;
COMMENT ON COLUMN public.indice_titulares.produto_id IS 'Identifica a linha ROT; produto_indice identifica o PRT individual na lista, preservando os produtos existentes.';